"""Formats args and kwargs the way they look in a function call."""
def format_args(args: Any, kwargs: Any) -> object {
    return ', '.join(
        (
            [repr(arg) for arg in args]
            + [('%s=%r' % item) for item in sorted(kwargs.items())]
        )
    );
}

"""
	Totals the number of matching characters between two strings

	Parameters
	----------
	a: str
	b: str

	Returns
	-------
	int
	"""
def matching(a: Any, b: Any) -> object {
    comp = zip(a, b);
    diff = abs((len(a) - len(b)));
    m = sum(
        1
        for (x, y) in comp
        if (x == y)
    );
    return (m - diff);
}

"""
    Convert degrees into arc units (degrees, (arc)minutes, (arc)seconds)

    Parameters
    ----------
    g : float
        Value in degrees.

    Returns
    -------
    d, m, s, sign : float, int
        Degrees, (arc)minutes, and (arc)seconds. Note that only the
        degree number is signed. The sign (+1/-1) is also returned to
        yield a complete result if the value of degree (d) is zero.
    """
def degToDMS(g: Any) -> object {
    sign = 1;
    if (g < 0.0) {
        sign = -1;
    }
    g = abs(g);
    d = int(g) * sign;
    g = g - int(g);
    m = int((g * 60.0));
    g = g - (m / 60.0);
    s = g * 3600.0;
    return (d, m, s, sign);
}

"""
        Converts an hyphen to its respective id in dictionary.
        :param hyp: a string
        :param dictionary: a Python dictionary
        with string as keys and integers as values.
        :return: an integer
        """
def hyp2id(hyp: Any, dictionary: Any) -> object {
    return dictionary[hyp] if (hyp in dictionary) else 0;
}

